#nullable enable
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using GameWorld.Core.Vfx;
using Shared.GameFormats.Vfx;

namespace GameWorld.Core.Test.Vfx;

[Category("Diagnostic")]
public class VfxNativeCurveBoundaryTests
{
    internal static JsonElement Fixture()
    {
        using var compressed = new MemoryStream(Convert.FromBase64String(NativeFixture));
        using var gzip = new GZipStream(compressed, CompressionMode.Decompress);
        using var bytes = new MemoryStream();
        gzip.CopyTo(bytes);
        var data = bytes.ToArray();
        Assert.That(Convert.ToHexStringLower(SHA256.HashData(data)), Is.EqualTo(FixtureSha256));
        using var document = JsonDocument.Parse(data);
        return document.RootElement.Clone();
    }

    public static IEnumerable<TestCaseData> OfficialFields() => Fixture().GetProperty("Cases").EnumerateArray()
        .Select(item => new TestCaseData(item.Clone()).SetName("NativeCurveBoundary_" + item.GetProperty("Name").GetString()));

    [TestCaseSource(nameof(OfficialFields))]
    public void OriginalCurveFields_MatchIndependentOfficialInstructionsWithoutChangingSerializedKeys(JsonElement item)
    {
        var text = item.GetProperty("Source").GetString()!;
        var field = item.GetProperty("Field").GetString()!;
        var preview = new VfxPreviewCurve(text, field, field == "ParticleScale" ? 1 : 0);
        Assert.That(VfxCurve.TryParse(text, out var editable), Is.True);
        Assert.That(editable!.ToString(), Is.EqualTo(text));
        var channels = item.GetProperty("Channels").EnumerateArray().ToArray();
        foreach (var axis in channels.Select(channel => channel.GetProperty("Name").GetString()![..^4]).Distinct())
        {
            preview.RequireChannels(axis);
            var modelTable = VfxModelNativeCurve.Create(text, field, axis);
            foreach (var upper in new[] { false, true })
            {
                var expected = channels.Single(channel => channel.GetProperty("Name").GetString() == axis + (upper ? "_max" : "_min"));
                var baked = expected.GetProperty("Baked").EnumerateArray().ToArray();
                for (var index = 0; index < baked.Length; ++index)
                    Assert.That(modelTable.SampleBoundAt(index, upper), Is.EqualTo(baked[index].GetSingle()).Within(.00001),
                        $"{axis}, upper={upper}, native float table[{index}]");
                // These rigid Bezier scale fields are consumed through ModelScaleTable above.
                // The existing generic sprite cubic candidate is a separate rendering contract.
                foreach (var sample in expected.GetProperty("Continuous").EnumerateArray().Where(_ => !text.Contains("bezier_c", StringComparison.Ordinal)))
                    Assert.That(preview.Sample(axis, sample.GetProperty("Phase").GetDouble(), upper ? 1 : 0),
                        Is.EqualTo(sample.GetProperty("Value").GetSingle()).Within(.00002), sample.ToString());
            }
        }
        Assert.That(editable.ToString(), Is.EqualTo(text), "Playback snapshots must not delete duplicate keys or populate authoring axes.");
    }

    [Test]
    public void FloatCoincidentKeys_KeepAuthorOrderEvenWhenTheDisplayOrderDiffers()
    {
        const string text = "x,0,1;.500000001,2,linear,linear,0,0,0,0,1|x_max,0,1;.5,9,linear,linear,0,0,0,0,1:x,1;0,1";
        const string sameChannel = "x,0,1;.500000001,2,linear,linear,0,0,0,0,1;.5,9,linear,linear,0,0,0,0,1:x,0;0,0";
        Assert.That(VfxCurve.TryParse(sameChannel, out var editable), Is.True);
        Assert.That(editable!.Channels[0].Points[0].Value, Is.EqualTo(9), "Editor display remains sorted by precise authored time.");
        Assert.That(editable.Channels[0].AuthoredPoints[0].Value, Is.EqualTo(2));
        var preview = new VfxPreviewCurve(sameChannel, "ParticleScale", 1);
        var model = VfxModelNativeCurve.Create(sameChannel, "ParticleScale");
        foreach (var time in new[] { 0, .25, .5, .75, 1 })
        {
            Assert.That(preview.Sample("x", time, .5f), Is.EqualTo(2));
            Assert.That(model.Sample(time, .5f), Is.EqualTo(2));
        }
        Assert.That(model.SampleCount, Is.EqualTo(128), "Native compression uses authored key count, before nearest-key selection.");
        Assert.That(editable.ToString(), Is.EqualTo(sameChannel));
        Assert.That(new VfxPreviewCurve(text, "ParticleScale", 1).Sample("x", .5, .5f), Is.EqualTo(5.5f),
            "Separate min/max channels must remain independently randomized.");
    }

    [Test]
    public void ModelAlpha_UsesNativeTablesRatherThanContinuousOrSpriteHalfSampling()
    {
        var item = Fixture().GetProperty("Cases").EnumerateArray().Single(item => item.GetProperty("Field").GetString() == "curve_alpha");
        var text = item.GetProperty("Source").GetString()!;
        var table = new VfxPreviewCurve(text, "curve_alpha", 1, nativeModelTable: true);
        var baked = item.GetProperty("Channels")[0].GetProperty("Baked").EnumerateArray().Select(value => value.GetSingle()).ToArray();
        for (var index = 0; index < 128; ++index)
            Assert.That(table.Sample("alpha", index / 127f, .37f), Is.EqualTo(baked[index]).Within(.00001));
        var continuous = new VfxPreviewCurve(text, "curve_alpha", 1);
        Assert.That(Math.Abs(table.Sample("alpha", .201, .37f) - continuous.Sample("alpha", .201, .37f)), Is.GreaterThan(.000005),
            "This asymmetric q-to-s control distinguishes model table interpolation from continuous curve evaluation.");
    }

    // Fresh official Utility75ed0 execution. The source fields are diagnostic extracts, not complete-effect visual acceptance.
    private const string FixtureSha256 = "8835825cc439f31d73dc8f1354cec915ba5234e39bebc20cddd5fae30ba9b74e";
    private const string NativeFixture = "";
}
